import { personas, insights, initialMessages, scenarios } from './data.js';

const app = document.querySelector('#app');
const state = { page:'overview', selected:'maya', step:0, messages:[...initialMessages], scenario:'size', tested:false, running:false, status:null, query:'Target women’s clothing and Walmart clothing' };
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avg = key => Math.round(personas.reduce((n,p)=>n+p[key],0)/personas.length);
const wins = personas.filter(p=>p.choice==='Target').length;
const icon = {overview:'◫',runs:'◎',focus:'◌',whatif:'◇'};
function modeLabel(){return state.status?.zoowork || state.status?.tavily || state.status?.band ? 'HYBRID MODE' : 'SEEDED DEMO';}
function shell(content){
  app.innerHTML = `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark"><span></span></span><div>persona<span>pulse</span><small>SHOPPER INTELLIGENCE</small></div></div><div class="workspace-label">WORKSPACE <span>⌄</span></div><div class="workspace"><span class="target-mini">◎</span><div><strong>Target Clothing</strong><small>vs. Walmart · US</small></div></div><div class="nav-label">ANALYSIS</div><nav aria-label="Main navigation">${[['overview','Overview'],['runs','Shopper runs'],['focus','Focus group'],['whatif','What-if test']].map(([id,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon[id]}</span>${label}${id==='runs'?'<span class="nav-count">10</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-divider"></div><div class="live-status"><span class="live-dot"></span>${modeLabel()}</div><p>Synthetic shoppers. Directional signals. Decisions still need real customer validation.</p><div class="profile"><span class="profile-avatar">PP</span><div><strong>PersonaPulse Lab</strong><small>Hackathon workspace</small></div><span>⋯</span></div></div></aside><main><header class="topbar"><div class="crumb">Workspace <span>/</span> Target Clothing <span>/</span> <strong>${{overview:'Overview',runs:'Shopper runs',focus:'Focus group',whatif:'What-if test'}[state.page]}</strong></div><div class="top-actions"><span class="run-stamp">LAST RUN · OCT 03, 2026</span><button class="button button-dark" id="runPanel">${state.running?'<span class="spinner"></span> Running panel':'↗ Run panel again'}</button></div></header><div class="page">${content}</div></main></div><div id="toast" role="status" aria-live="polite"></div>`;
  document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{state.page=el.dataset.page;render()});
  document.querySelector('#runPanel').onclick=runPanel;
}
function pageHead(kicker,title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`}
function avatar(p,cls=''){return `<span class="avatar ${p.tone} ${cls}">${p.initials}</span>`}
function overview(){
  const cards=[['Panel preference',`${wins} / 10`,'shoppers chose Target','positive'],['Target confidence',`${avg('target')}<small>/100</small>`,'average shopper score','neutral'],['Walmart confidence',`${avg('walmart')}<small>/100</small>`,'average shopper score','neutral'],['Top conversion leak','Size + fit','3 shoppers hesitated','warn']];
  shell(`${pageHead('COMPARATIVE PANEL · WOMEN’S & FAMILY CLOTHING','See where shoppers hesitate.','Ten distinct shopping missions. One direct comparison between Target and Walmart.',`<div class="head-badge"><span class="pulse-dot"></span> PANEL COMPLETE <span>10 / 10</span></div>`)}<div class="mission-bar"><div><span class="label">MISSION</span><strong>Find clothing that fits your needs, budget and timing</strong></div><div><span class="label">MERCHANT</span><strong><span class="target-dot">●</span> Target</strong></div><div><span class="label">BENCHMARK</span><strong><span class="walmart-spark">✦</span> Walmart</strong></div><button class="text-button" data-page="runs">View all runs →</button></div><div class="metrics">${cards.map(([label,value,desc,type])=>`<div class="metric"><span class="metric-label">${label}</span><strong class="metric-value ${type}">${value}</strong><span class="metric-desc">${desc}</span></div>`).join('')}</div><div class="overview-grid"><section class="panel comparison"><div class="panel-head"><div><div class="eyebrow">01 / BENCHMARK</div><h2>Shopper confidence</h2><p>How likely each persona was to complete their mission</p></div><span class="tiny-badge">10 SHOPPERS</span></div><div class="legend"><span><i class="target-key"></i> Target</span><span><i class="walmart-key"></i> Walmart</span></div><div class="chart">${personas.map(p=>`<div class="chart-row" title="${esc(p.name)}: Target ${p.target}, Walmart ${p.walmart}"><span>${esc(p.name.split(' ')[0])}</span><div class="bars"><i class="target-bar" style="width:${p.target}%"></i><i class="walmart-bar" style="width:${p.walmart}%"></i></div><b>${p.choice==='Target'?'T':'W'}</b></div>`).join('')}</div><div class="chart-foot">Target wins on style and pickup · Walmart wins on value and availability</div></section><section class="panel recommendations"><div class="panel-head"><div><div class="eyebrow">02 / ACTIONS</div><h2>What to fix first</h2><p>Ranked by how often a shopper hit the barrier</p></div></div><div class="insights">${insights.map(x=>`<div class="insight"><span class="insight-rank">${x.rank}</span><div><span class="tag">${x.tag}</span><h3>${x.title}</h3><p>${x.detail}</p><span class="impact">↗ ${x.impact}</span></div></div>`).join('')}</div><button class="wide-link" data-page="whatif">Test a change before shipping <span>→</span></button></section></div><div class="footnote">DEMO DATA · These are simulated shopper outcomes, not measured conversion or verified live prices. Use the what-if test to explore hypotheses.</div>`);
}
function runs(){ const p=personas.find(x=>x.id===state.selected);
  shell(`${pageHead('TEN INDIVIDUAL JOURNEYS','Shopper runs','Follow the decision trail behind every score and preference.',`<div class="small-stat"><strong>10</strong><span>PERSONAS<br>COMPARED</span></div>`)}<div class="runs-layout"><section class="panel shopper-list"><div class="list-header"><strong>Shopper panel</strong><span>10 agents</span></div>${personas.map(x=>`<button class="shopper-row ${x.id===p.id?'selected':''}" data-persona="${x.id}">${avatar(x)}<span class="shopper-info"><strong>${x.name}</strong><small>${x.type}</small></span><span class="choice ${x.choice.toLowerCase()}">${x.choice}</span></button>`).join('')}</section><section class="run-detail"><div class="detail-top"><div class="detail-identity">${avatar(p,'large')}<div><span class="eyebrow">PERSONA ${String(personas.indexOf(p)+1).padStart(2,'0')} / 10</span><h2>${p.name}</h2><p>${p.age} · ${p.location} · ${p.type}</p></div></div><span class="choice big ${p.choice.toLowerCase()}">${p.choice} preferred</span></div><div class="mission-card"><div><span class="label">SHOPPING MISSION</span><h3>${p.need}</h3></div><div><span class="label">BUDGET</span><strong>${p.budget}</strong></div><div><span class="label">PRIORITY</span><strong>${p.priority}</strong></div></div><div class="score-compare"><div><span><i class="target-key"></i> Target</span><b>${p.target}<small>/100</small></b><div class="score-track"><i style="width:${p.target}%;background:#db5c55"></i></div></div><div><span><i class="walmart-key"></i> Walmart</span><b>${p.walmart}<small>/100</small></b><div class="score-track"><i style="width:${p.walmart}%;background:#e4ac47"></i></div></div></div><div class="replay-head"><div><div class="eyebrow">REPLAY / DECISION TRACE</div><h2>How ${p.name.split(' ')[0]} decided</h2></div><span>STEP ${state.step+1} OF ${p.steps.length}</span></div><div class="replay-card"><div class="timeline">${p.steps.map((s,i)=>`<button class="timeline-step ${i===state.step?'current':''}" data-step="${i}"><span>${String(i+1).padStart(2,'0')}</span><strong>${s[0]}</strong></button>`).join('')}</div><div class="replay-content"><span class="tag">${p.steps[state.step][0].toUpperCase()}</span><h3>${p.steps[state.step][1]}</h3><p>${state.step===p.steps.length-1?p.quote:'The agent records what it looked for and how each site affected purchase confidence.'}</p><div class="replay-controls"><button id="prevStep" ${state.step===0?'disabled':''}>← Previous</button><button id="nextStep" ${state.step===p.steps.length-1?'disabled':''}>Next step →</button></div></div></div><div class="friction"><span>⚑ KEY FRICTION</span><strong>${p.friction}</strong></div></section></div>`);
  document.querySelectorAll('[data-persona]').forEach(el=>el.onclick=()=>{state.selected=el.dataset.persona;state.step=0;render()});
  document.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>{state.step=Number(el.dataset.step);render()});
  document.querySelector('#prevStep').onclick=()=>{state.step--;render()};document.querySelector('#nextStep').onclick=()=>{state.step++;render()};
}
function focus(){
  shell(`${pageHead('BAND-STYLE COORDINATION ROOM','Ask the shopper panel','Explore disagreements with a moderated, replayable multi-agent conversation.',`<span class="tiny-badge room-badge"><span class="live-dot"></span> FOCUS ROOM 01</span>`)}<div class="focus-layout"><section class="panel room"><div class="room-header"><div><strong>Target × Walmart · Clothing</strong><span>Moderator + 10 shopper agents + analyst</span></div><span class="tiny-badge">AUDITABLE TRANSCRIPT</span></div><div class="messages" id="messages">${state.messages.map(m=>`<div class="message ${m.type}"><div class="message-icon">${m.type==='moderator'?'✦':m.type==='summary'?'↗':m.speaker.split(' ').map(x=>x[0]).join('')}</div><div><div class="message-meta"><strong>${esc(m.speaker)}</strong><span>${esc(m.time)}</span></div><p>${esc(m.text)}</p></div></div>`).join('')}</div><form id="askForm" class="ask-form"><span>@</span><input name="question" aria-label="Ask the focus group" placeholder="Ask the panel a question…" autocomplete="off" required maxlength="300"><button class="button button-dark">Ask panel ↗</button></form></section><aside class="focus-side"><section class="panel participants"><div class="eyebrow">IN THIS ROOM</div><h3>Participants <span>12</span></h3><div class="participant"><span class="avatar moderator-avatar">✦</span><div><strong>Moderator</strong><small>Coordinates the room</small></div><i></i></div>${personas.slice(0,5).map(p=>`<div class="participant">${avatar(p)}<div><strong>${p.name}</strong><small>${p.type}</small></div><i></i></div>`).join('')}<div class="more-participants">+ 5 more shoppers and analyst</div></section><section class="panel room-note"><div class="eyebrow">WHY A ROOM?</div><h3>One question. Different viewpoints.</h3><p>The moderator addresses specific shoppers. Their answers and the analyst synthesis stay in one replayable record.</p><div>◌ &nbsp;Mention-directed turns<br>◷ &nbsp;Timestamped transcript<br>↗ &nbsp;Shared summary</div></section></aside></div>`);
  document.querySelector('#askForm').onsubmit=askPanel;
  document.querySelector('#messages').scrollTop=99999;
}
function whatif(){const s=scenarios.find(x=>x.id===state.scenario);
  shell(`${pageHead('DECISION LAB / WHAT-IF TEST','Test a change before shipping','Estimate how the same ten shoppers might respond to a merchandising fix.',`<span class="tiny-badge">SAME PANEL · NEW EXPERIENCE</span>`)}<div class="whatif-grid"><section class="panel scenario-panel"><div class="eyebrow">01 / CHOOSE AN INTERVENTION</div><h2>What should Target change?</h2><p>Select one fix to rerun against the existing shopper panel.</p><div class="scenario-list">${scenarios.map(x=>`<button class="scenario ${x.id===s.id?'chosen':''}" data-scenario="${x.id}"><span class="radio"></span><span><strong>${x.name}</strong><small>${x.desc}</small></span></button>`).join('')}</div><button class="button button-dark test-button" id="testScenario">↗ Run what-if test</button><div class="scenario-disclaimer">Directional simulation · No claim of measured conversion lift</div></section><section class="panel outcome-panel"><div class="eyebrow">02 / PROJECTED RESPONSE</div>${state.tested?`<div class="outcome-intro"><span class="result-icon">↗</span><h2>${s.uplift} point confidence lift</h2><p>Estimated gain for affected shoppers in this simulated change.</p></div><div class="before-after"><div><span>CURRENT TARGET SCORE</span><strong>${avg('target')}</strong></div><span class="arrow">→</span><div><span>SCENARIO SCORE</span><strong>${Math.min(100,Math.round(avg('target')+s.uplift*s.converts.length/personas.length))}</strong></div></div><div class="outcome-body"><div class="eyebrow">SHOPPERS MOST LIKELY TO CHANGE</div>${s.converts.map(id=>{const p=personas.find(x=>x.id===id);return `<div class="switcher">${avatar(p)}<div><strong>${p.name}</strong><small>${p.friction}</small></div><span>↗</span></div>`}).join('')}<p>${s.reason}</p></div><button class="wide-link" data-page="runs">Inspect shopper evidence <span>→</span></button>`:`<div class="empty-outcome"><span>◇</span><h2>Your next decision starts here.</h2><p>Choose an intervention and run it against the same ten shopper missions to see whose decision might change.</p></div><div class="preview-list"><span>THE TEST WILL SHOW</span><div>↗ &nbsp;Projected confidence change</div><div>◎ &nbsp;Which shoppers might switch</div><div>◫ &nbsp;The friction this change addresses</div></div>`}</section></div><div class="footnote">WHAT-IF RESULTS ARE ILLUSTRATIVE · Validate any change with real shopper research or an A/B test before making revenue claims.</div>`);
  document.querySelectorAll('[data-scenario]').forEach(el=>el.onclick=()=>{state.scenario=el.dataset.scenario;state.tested=false;render()});
  document.querySelector('#testScenario').onclick=()=>{state.tested=true;render();toast('Scenario completed for all 10 shoppers')};
}
function render(){({overview,runs,focus,whatif}[state.page])();document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{state.page=el.dataset.page;render()})}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)}
async function post(path,payload){const response=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error('unavailable');return response.json()}
async function runPanel(){if(state.running)return;state.running=true;render();try{await Promise.allSettled([post('/api/extract',{query:state.query}),post('/api/run',{mission:'Compare Target and Walmart clothing',personas:personas.map(p=>({id:p.id,need:p.need,budget:p.budget}))})]);}catch{}setTimeout(()=>{state.running=false;state.page='overview';render();toast('Panel complete · 10 shopper journeys ready')},900)}
async function askPanel(event){event.preventDefault();const input=event.target.question;const question=input.value.trim();if(!question)return;input.value='';const time=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});state.messages.push({speaker:'You',type:'user',time,text:question});const q=question.toLowerCase();let respondents=q.includes('price')||q.includes('budget')||q.includes('cost')?['jordan','priya']:q.includes('size')||q.includes('fit')?['samira','maya']:q.includes('promo')||q.includes('sale')?['omar','denise']:['maya','jordan'];for(const id of respondents){const p=personas.find(x=>x.id===id);state.messages.push({speaker:p.name,type:'persona',time,text:p.quote})}state.messages.push({speaker:'Analyst',type:'summary',time,text:q.includes('price')||q.includes('budget')||q.includes('cost')?'Value shoppers want a visible full-basket total before checkout.':q.includes('size')||q.includes('fit')?'Fit confidence and visible availability are the clearest opportunities.':'The panel’s decision turns on clear value, size confidence, and outfit inspiration.'});render();try{const result=await post('/api/focus',{message:question});if(result.mode==='live')toast('Question also sent to the Band room')}catch{toast('Using the seeded focus group transcript')}}
fetch('/api/status').then(r=>r.ok?r.json():null).then(data=>{state.status=data;render()}).catch(()=>{});
render();
